{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PRESENT",
      "chunk_id": "text_2",
      "quote": "However, there is currently a lack of systematically compiled evidence assessing their impact. To close this research gap, we conducted a systematic review on the effects of minimum volume standards in hospitals.",
      "reason": "The passage explicitly states the current knowledge gap and uncertainty, fulfilling the requirement to describe the state of knowledge and important uncertainties."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_31",
      "quote": "There is strong evidence for the existence of a volume‑outcome relationship in healthcare, which provides the rationale for the implementation of minimum volume standards in hospitals. ... Yet, there is a considerable lack of evidence for the effects of the minimum volume standards already in place.",
      "reason": "The text explains why the review is needed by highlighting the importance of the topic and the lack of existing evidence on the effects of minimum volume standards."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "No evidence is provided that similar systematic reviews exist or that an update/replication is being performed; therefore the conditional requirement does not apply."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "Minimum volume standards are cut‑off thresholds for hospitals allowing only those hospitals above a defined threshold to perform a given medical procedure in the future. As a policy tool, minimum volume standards aim at concentrating the procedures for which they are in effect in hospitals with higher volumes. This objective is based on evidence of the volume‑outcome relationship.",
      "reason": "The passage briefly describes the mechanism of action of the intervention (minimum volume standards) by explaining how they concentrate procedures in higher‑volume hospitals to improve outcomes."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The manuscript does not present a logic model for the intervention; no evidence of such a model is found, so the conditional element is not applicable."
    }
  ],
  "confidence": 95
}

